gold.schema_ddl:
CREATE TABLE categorie (
    id INT PRIMARY KEY,
    nome TEXT NOT NULL UNIQUE,
    categoria_padre_id INT REFERENCES categorie(id)
);

CREATE TABLE prodotti (
    id INT PRIMARY KEY,
    nome TEXT NOT NULL,
    categoria_id INT NOT NULL REFERENCES categorie(id),
    prezzo NUMERIC(10,2) CHECK (prezzo >= 0),
    quantita_disponibile INT CHECK (quantita_disponibile >= 0)
);
